class Solution {
    public: int kSimilarity(string s1,string s2){
        queue<string> pending;
        unordered_set<string> seen{
            s1
        };
        pending.push(s1);
        int swaps=0;
        while(!pending.empty()){
            for(int size=pending.size();size;--size){
                string current=pending.front();
                pending.pop();
                if(current==s2)return swaps;
                int i=0;
                while(current[i]==s2[i])++i;
                for(int j=i+1;j<(int)current.size();++j)if(current[j]==s2[i]&&current[j]!=s2[j]){
                    swap(current[i],current[j]);
                    if(seen.insert(current).second)pending.push(current);
                    swap(current[i],current[j]);
                }
            }
            ++swaps;
        }
        return -1;
    }
};
